//! Standard content (Onshape's fastener library): bolts and screws, nuts,
//! washers and pins of the ANSI, DIN and ISO standards, picked in the Insert
//! dialog by Standard › Category › Class › Component, then Size and Length.
//!
//! Each part is generated by a built-in Feature Studio script ([`SOURCE`]),
//! evaluated like a custom feature in a one-feature Part Studio
//! ([`part_studio`]) with fixed feature ids, so face names (and the mates on
//! them) stay stable across sessions. The parts carry explicit mate
//! connectors like Onshape's: bolts and screws one under the head (flush
//! with the top for countersunk heads), nuts and washers one on each face.

use crate::configuration::ConfigValues;
use crate::custom::{CustomFeatureProvider, DocumentScripts};
use crate::document::{Document, TabContent, TabId};
use crate::params::ParamValue;
use crate::partstudio::PartStudio;
use crate::reference::{BodyId, FeatureId};
use crate::regen::{RegenOptions, RegenResult, Regenerator};
use noshape_units::{ExprValue, UnitPrefs};
use serde::{Deserialize, Serialize};
use std::sync::{Arc, LazyLock};

/// Tab id of the built-in standard content Feature Studio (never a tab of a
/// user document).
pub const STANDARD_TAB: TabId = TabId(0x5354_445f_434f_4e54);

/// Feature id of the generated part.
const PART_FEATURE: FeatureId = FeatureId(0x5354_4401);

/// The part of a regenerated standard part (its only body).
pub fn part_body(r: &RegenResult) -> Option<BodyId> {
    match r.context.bodies.as_slice() {
        [b] => Some(b.id.clone()),
        _ => None,
    }
}

/// Which standard content item an instance is, with its size (and length
/// for bolts, screws and pins). Strings are catalogue names.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(from = "SpecFile")]
pub struct StandardSpec {
    pub standard: String,
    pub category: String,
    pub class: String,
    pub component: String,
    pub size: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub length: Option<String>,
    /// Head slot (components with the option; None = the default, on).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub head_slot: Option<bool>,
    /// Material and Finish (None = the defaults, [`MATERIALS`][0] and [`FINISHES`][0]).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub material: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub finish: Option<String>,
    /// Washer Series (ANSI Type A: Narrow / Wide; None = Narrow).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub series: Option<String>,
    /// Nut Bearing face (metric: Washer face / Chamfered; None = the first).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bearing_face: Option<String>,
}

/// A spec as stored; documents saved before the catalogue took Onshape's
/// names ("ANSI", "Bolts & Screws", sizes "1/4", lengths "1 1/4 in") load
/// with today's names.
#[derive(Deserialize)]
struct SpecFile {
    standard: String,
    category: String,
    class: String,
    component: String,
    size: String,
    #[serde(default)]
    length: Option<String>,
    #[serde(default)]
    head_slot: Option<bool>,
    #[serde(default)]
    material: Option<String>,
    #[serde(default)]
    finish: Option<String>,
    #[serde(default)]
    series: Option<String>,
    #[serde(default)]
    bearing_face: Option<String>,
}

impl From<SpecFile> for StandardSpec {
    fn from(f: SpecFile) -> Self {
        let rename = |s: String| match s.as_str() {
            "ANSI" => ANSI.to_string(),
            "Bolts & Screws" => BOLTS.to_string(),
            "Pins & Studs" => ANSI_PINS.to_string(),
            _ => s,
        };
        let mut spec = StandardSpec { standard: rename(f.standard), category: rename(f.category), class: f.class, component: f.component, size: f.size, length: f.length, head_slot: f.head_slot, material: f.material, finish: f.finish, series: f.series, bearing_face: f.bearing_face };
        if let Some(c) = component(&spec)
            && c.inch
        {
            // "1/4" → "1/4-20" (the thread designation of the size).
            if c.size(&spec.size).is_none()
                && let Some(s) = c.sizes.iter().find(|s| s.name.split('-').next() == Some(spec.size.as_str()))
            {
                spec.size = s.name.to_string();
            }
            // "1 1/4 in" → "1.25" (the nearest of the offered lengths).
            if let Some(v) = spec.length.as_deref().filter(|l| l.ends_with(" in")).and_then(length_value) {
                spec.length = INCH_LENGTHS.iter().min_by(|a, b| (c.length_m(a).unwrap_or(0.0) - v).abs().total_cmp(&(c.length_m(b).unwrap_or(0.0) - v).abs())).map(|l| l.to_string());
            }
        }
        spec
    }
}

/// Geometry family of a component (one script feature each).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shape {
    HexBolt,
    SocketHead,
    ButtonHead,
    Countersunk,
    SetScrew,
    HexNut,
    Washer,
    Pin,
}

impl Shape {
    fn feature(self) -> &'static str {
        match self {
            Shape::HexBolt => "hexBolt",
            Shape::SocketHead => "socketHeadScrew",
            Shape::ButtonHead => "buttonHeadScrew",
            Shape::Countersunk => "countersunkScrew",
            Shape::SetScrew => "setScrew",
            Shape::HexNut => "hexNut",
            Shape::Washer => "washer",
            Shape::Pin => "pin",
        }
    }
    /// Whether the component has a length (bolts, screws, pins).
    pub fn has_length(self) -> bool {
        !matches!(self, Shape::HexNut | Shape::Washer)
    }
    /// Nuts and washers fit over a shaft: auto-size rounds up.
    pub fn fits_over(self) -> bool {
        matches!(self, Shape::HexNut | Shape::Washer)
    }
}

/// One size row. Values are in the component's unit (mm, or inches for
/// ANSI): `d` nominal diameter (washers: hole diameter), then per shape:
/// hex bolt `a` across flats, `b` head height; socket / button /
/// countersunk heads `a` head diameter, `b` head height, `c` socket size;
/// set screws `c` socket size; nuts `a` across flats, `b` height;
/// washers `a` outer diameter, `b` thickness.
#[derive(Clone, Copy, Debug)]
pub struct Size {
    pub name: &'static str,
    pub d: f64,
    pub a: f64,
    pub b: f64,
    pub c: f64,
}

const fn sz(name: &'static str, d: f64, a: f64, b: f64, c: f64) -> Size {
    Size { name, d, a, b, c }
}

/// A component of the catalogue.
#[derive(Debug)]
pub struct Component {
    pub standard: &'static str,
    pub category: &'static str,
    pub class: &'static str,
    pub name: &'static str,
    pub shape: Shape,
    pub inch: bool,
    pub sizes: &'static [Size],
    /// Offers the Head slot option (slotted head instead of a socket).
    pub head_slot: bool,
    /// Shows the Thread length row.
    pub thread_length: bool,
}

impl Component {
    fn unit(&self) -> f64 {
        if self.inch { 25.4 } else { 1.0 }
    }
    pub fn size(&self, name: &str) -> Option<&Size> {
        self.sizes.iter().find(|s| s.name == name)
    }
    /// Lengths offered for a size (names as shown, e.g. "20 mm" or "1 in").
    pub fn lengths(&self, size: &Size) -> Vec<String> {
        if !self.shape.has_length() {
            return Vec::new();
        }
        if self.inch {
            INCH_LENGTHS.iter().map(|l| l.to_string()).collect()
        } else {
            const L: [f64; 30] = [3., 4., 5., 6., 8., 10., 12., 14., 16., 20., 25., 30., 35., 40., 45., 50., 55., 60., 65., 70., 75., 80., 90., 100., 110., 120., 130., 140., 150., 160.];
            let (lo, hi) = self.length_range(size);
            L.iter().filter(|v| **v >= lo - 1e-9 && **v <= hi + 1e-9).map(|v| format!("{v} mm")).collect()
        }
    }
    fn length_range(&self, s: &Size) -> (f64, f64) {
        match self.shape {
            Shape::HexBolt => (2.0 * s.d, 12.0 * s.d),
            Shape::SetScrew => (s.d * 0.75, 6.0 * s.d),
            Shape::Pin => (2.0 * s.d, 10.0 * s.d),
            Shape::Countersunk => (1.5 * s.d, 10.0 * s.d),
            _ => (1.25 * s.d, 12.0 * s.d),
        }
    }
    /// Default length for a size: the first offered (live: "the first
    /// Length for that size").
    pub fn default_length(&self, size: &Size) -> Option<String> {
        self.lengths(size).first().cloned()
    }
    /// A length name in meters: "20 mm", "1 1/4 in", or a bare number in
    /// the component's unit (ANSI inch "0.25").
    pub fn length_m(&self, name: &str) -> Option<f64> {
        length_value(name).or_else(|| name.trim().parse::<f64>().ok().map(|v| v * self.unit() * 1e-3))
    }
    /// The Series select (live: ANSI Type A flat washer, Narrow / Wide).
    pub fn series(&self) -> &'static [&'static str] {
        if self.inch && self.shape == Shape::Washer { &["Narrow", "Wide"] } else { &[] }
    }
    /// The Drive type select (live: socket head screws "Hex").
    pub fn drive_type(&self) -> Option<&'static str> {
        matches!(self.shape, Shape::SocketHead | Shape::ButtonHead | Shape::SetScrew).then_some("Hex").or((self.shape == Shape::Countersunk && !self.head_slot).then_some("Hex"))
    }
    /// The Bearing face select (live: ANSI hex nuts Chamfered; ISO 4032
    /// Washer face / Chamfered).
    pub fn bearing_faces(&self) -> &'static [&'static str] {
        match self.shape {
            Shape::HexNut if self.inch => &["Chamfered"],
            Shape::HexNut => &["Washer face", "Chamfered"],
            _ => &[],
        }
    }
    /// Thread length offered for a size and length (bolts and screws, live):
    /// inch 2D + 1/4 in (ASME B18.2.1), metric 2d + 6 mm (ISO 4014), never
    /// longer than the bolt.
    pub fn thread_length(&self, size: &Size, length: &str) -> Option<String> {
        if !(self.thread_length || matches!(self.shape, Shape::HexBolt | Shape::SocketHead | Shape::ButtonHead | Shape::Countersunk)) {
            return None;
        }
        let l = self.length_m(length)?;
        let t = if self.inch { (2.0 * size.d + 0.25) * self.unit() * 1e-3 } else { (2.0 * size.d + 6.0) * 1e-3 };
        if t >= l - 1e-9 {
            return Some(length.to_string());
        }
        let v = t * 1e3 / self.unit();
        let v = format!("{}", (v * 1e4).round() / 1e4);
        Some(if self.inch { v } else { format!("{v} mm") })
    }
    /// Nominal diameter in meters.
    pub fn diameter_m(&self, size: &Size) -> f64 {
        size.d * self.unit() * 1e-3
    }
}

/// Parse a catalogue length ("20 mm", "1 1/4 in") into meters.
pub fn length_value(s: &str) -> Option<f64> {
    if let Some(v) = s.strip_suffix(" mm") {
        return v.trim().parse::<f64>().ok().map(|v| v * 1e-3);
    }
    let v = s.strip_suffix(" in")?.trim();
    let mut total = 0.0;
    for part in v.split_whitespace() {
        total += match part.split_once('/') {
            Some((n, d)) => n.parse::<f64>().ok()? / d.parse::<f64>().ok()?,
            None => part.parse::<f64>().ok()?,
        };
    }
    Some(total * 0.0254)
}

